function tree(x,z,size,kind=0){const base=project(x,0,z),top=project(x,size*1.9,z);if(!base||!top)return;let h=base.y-top.y;if(h<2)return;let w=h*(kind?0.68:.56);ctx.fillStyle='#584431';ctx.fillRect(base.x-w*.09,base.y-h*.52,w*.18,h*.54);if(kind){polygon([{x:base.x,y:top.y},{x:base.x-w*.62,y:top.y+h*.48},{x:base.x+w*.62,y:top.y+h*.48}],'#23865e');polygon([{x:base.x,y:top.y+h*.18},{x:base.x-w*.49,y:top.y+h*.68},{x:base.x+w*.49,y:top.y+h*.68}],'#2da76a')}else{ctx.fillStyle='#278553';ctx.beginPath();ctx.ellipse(base.x,top.y+h*.34,w*.65,h*.42,0,0,TAU);ctx.fill();ctx.fillStyle='#48b976';ctx.beginPath();ctx.ellipse(base.x-w*.16,top.y+h*.27,w*.34,h*.25,-.2,0,TAU);ctx.fill()}}
function drawKart(x,y,scale,color='#f54460',tilt=0){ctx.save();ctx.translate(x,y);ctx.rotate(tilt);ctx.scale(scale,scale);ctx.shadowColor='#122';ctx.shadowBlur=12;ctx.fillStyle='#17212a';ctx.fillRect(-28,-15,14,25);ctx.fillRect(14,-15,14,25);ctx.shadowBlur=0;ctx.fillStyle='#e7e8d8';ctx.fillRect(-30,-14,8,19);ctx.fillRect(22,-14,8,19);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-22,14);ctx.lineTo(-18,-16);ctx.quadraticCurveTo(-15,-27,0,-28);ctx.quadraticCurveTo(15,-27,18,-16);ctx.lineTo(22,14);ctx.quadraticCurveTo(0,22,-22,14);ctx.fill();ctx.fillStyle='#ffbd48';ctx.fillRect(-13,-23,26,8);ctx.fillStyle='#b8f5fb';ctx.beginPath();ctx.ellipse(0,-7,11,8,0,0,TAU);ctx.fill();ctx.fillStyle='#f9fbdf';ctx.beginPath();ctx.arc(-14,12,4,0,TAU);ctx.arc(14,12,4,0,TAU);ctx.fill();ctx.fillStyle='#ffea76';ctx.fillRect(-17,15,7,3);ctx.fillRect(10,15,7,3);ctx.restore()}
function drawCoin(u,side){const p=at(u),v=project(p.x+p.nx*side,2.4,p.z+p.nz*side);if(!v)return;let r=Math.max(2,Math.min(18,cam.focal/v.depth*1.1));ctx.save();ctx.translate(v.x,v.y);ctx.scale(.7+.3*Math.abs(Math.sin(runTime*5+u*50)),1);ctx.fillStyle='#ffdf55';ctx.strokeStyle='#fff4a8';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,r,r*1.25,0,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle='#d7931a';ctx.font=`bold ${r}px sans-serif`;ctx.textAlign='center';ctx.fillText('★',0,r*.35);ctx.restore()}
const trees=[];for(let i=0;i<110;i++){let u=i/110;const p=at(u);for(const s of [-1,1]){const spread=18+((i*37+s*13)%17);trees.push({x:p.x+p.nx*s*spread,z:p.z+p.nz*s*spread,size:5+((i*19)%6),kind:(i%4===0)?1:0,u})}}
const coinSpots=Array.from({length:34},(_,i)=>({u:(.018+i*.0294)%1,side:(i%2?3:-3)}));
function drawWorld(){drawSky();updateCamera();const start=Math.floor(progress*N)-220,end=start+600,objects=[];
for(let i=start;i<end;i++){let idx=(i%N+N)%N,j=(idx+1)%N,a=track[idx],b=track[j];const mid=at((i+.5)/N),pr=project(mid.x,0,mid.z);if(pr&&pr.depth>1)objects.push({depth:pr.depth,draw:()=>{const half=6.7,curb=7.6,outer=8.5;let aL=ground(a.x+a.nx*outer,a.z+a.nz*outer),aR=ground(a.x-a.nx*outer,a.z-a.nz*outer),bL=ground(b.x+b.nx*outer,b.z+b.nz*outer),bR=ground(b.x-b.nx*outer,b.z-b.nz*outer);quad(aL,bL,bR,aR,'#9b8c68');aL=ground(a.x+a.nx*curb,a.z+a.nz*curb);aR=ground(a.x-a.nx*curb,a.z-a.nz*curb);bL=ground(b.x+b.nx*curb,b.z+b.nz*curb);bR=ground(b.x-b.nx*curb,b.z-b.nz*curb);quad(aL,bL,bR,aR,i%8<4?'#f4f2dc':'#e64e54');aL=ground(a.x+a.nx*half,a.z+a.nz*half);aR=ground(a.x-a.nx*half,a.z-a.nz*half);bL=ground(b.x+b.nx*half,b.z+b.nz*half);bR=ground(b.x-b.nx*half,b.z-b.nz*half);quad(aL,bL,bR,aR,'#4d5862');if(i%8<4){const yellow='#e5c85a';let l1=ground(a.x+a.nx*.16,a.z+a.nz*.16,.04),l2=ground(b.x+b.nx*.16,b.z+b.nz*.16,.04),r1=ground(a.x-a.nx*.16,a.z-a.nz*.16,.04),r2=ground(b.x-b.nx*.16,b.z-b.nz*.16,.04);quad(l1,l2,r2,r1,yellow)}
// start/finish checker strip
if(idx===0){for(let k=0;k<8;k++){let l=-6.5+k*1.625,r=l+1.625;quad(ground(a.x+a.nx*l,a.z+a.nz*l,.08),ground(b.x+b.nx*l,b.z+b.nz*l,.08),ground(b.x+b.nx*r,b.z+b.nz*r,.08),ground(a.x+a.nx*r,a.z+a.nz*r,.08),k%2?'#f7f3dc':'#202b34')}}}})}
for(const t of trees){let d=((t.u-progress+1)%1);if(d>.48&&d<.98)continue;const q=project(t.x,1,t.z);if(q&&q.depth>1)objects.push({depth:q.depth,draw:()=>tree(t.x,t.z,t.size,t.kind)})}
// floating ring coins
for(const c of coinSpots){if(coins&&false)continue;let d=(c.u-progress+1)%1;if(d>.22)continue;const p=at(c.u),q=project(p.x+p.nx*c.side,2.4,p.z+p.nz*c.side);if(q&&q.depth>1)objects.push({depth:q.depth,draw:()=>drawCoin(c.u,c.side)})}
objects.sort((a,b)=>b.depth-a.depth);for(const o of objects)o.draw();
// distant trackside grandstand balloons
const p=at(progress);const kartPos=project(p.x+p.nx*lateral,0,p.z+p.nz*lateral);const driftTilt=(keys.left?-1:keys.right?1:0)*(keys.drift?.12:.055);drawKart(W*.5,H*.82,Math.min(1.05,Math.max(.7,H/750)),boost>0?'#d8ff45':'#f04463',driftTilt);
// speed streaks when boosting
if(boost>0){ctx.strokeStyle='#edff9d88';ctx.lineWidth=2;for(let i=0;i<12;i++){let x=Math.random()*W,y=Math.random()*H*.7;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(x-W/2)*.08,y+25+Math.random()*45);ctx.stroke()}}
}

